      "content": "#!/usr/bin/env bash\n# dsh-loopback-guard -- keep tenants from reaching each other's DSH instances.\n#\n# Why: every per-user DSH instance listens on 127.0.0.1:<port> and DSH decides\n# \"privileged request\" by the Host header alone (the gateway itself relies on\n# this). Any tenant's agent can already run arbitrary shell commands, so\n# without this guard tenant A could curl 127.0.0.1:<B-port> with a forged\n# Host header and read/write B's settings, sessions and API-key store.\n# OS-level file isolation cannot see loopback HTTP; the firewall can.\n#\n# Model (v2, destination-scoped): a dedicated iptables OUTPUT chain where\n#   1. each dsh-<name> OS account may connect to its OWN instance port,\n#   2. each dsh-<name> account is REJECTed for every other tenant port and\n#      for the gateway port (spoofing the gateway = spoofing another user),\n#   3. replies (sport = own port) and all non-tenant UIDs pass untouched.\n# NOTE: never reject by uid alone - a blanket per-uid REJECT in OUTPUT also\n# kills the kernel-generated reply path of the tenant's own instance, which\n# turns every tenant connection into a silent timeout.\n#\n# Usage (run as root):\n#   dsh-loopback-guard --apply <osuser>:<port> [<osuser>:<port> ...]\n#     Rebuild the rule set from the FULL user list (idempotent, clears stale\n#     rules first). The gateway port should be passed as gw:<port>.\n#   dsh-loopback-guard --check\n#     Exit 0 if the chain exists and is hooked into OUTPUT.\n#   dsh-loopback-guard --remove\n#     Remove the chain entirely (back to open state).\n#\n# Notes:\n# - IPv4 only: the instances bind 127.0.0.1; ::1 has no listener.\n# - Tenant agents that legitimately need another local TCP service will pass;\n#   extend the REJECT list per service if that ever changes.\nset -euo pipefail\n\nCHAIN=DSH_LOOPBACK_GUARD\ncomment=\"dsh-loopback-guard\"\nGW_PORT=\"${GW_PORT:-3100}\"\n\nipt() { iptables -w 5 \"$@\"; }\n\nvalid_spec() {\n  # <osuser>:<port>, osuser must be dsh-<lowercase alnum/_/->, port numeric.\n  local spec=\"$1\" user=\"$2\" port=\"$3\"\n  if [ -z \"$user\" ] || [ -z \"$port\" ]; then\n    echo \"invalid spec: $spec (want <osuser>:<port>)\" >&2; return 1\n  fi\n  case \"$user\" in\n    dsh-[a-z0-9_-]*) ;;\n    *) echo \"invalid osuser in spec: $spec\" >&2; return 1 ;;\n  esac\n  case \"$port\" in\n    ''|*[!0-9]*) echo \"invalid port in spec: $spec\" >&2; return 1 ;;\n  esac\n  return 0\n}\n\nhook_output() {\n  if ! ipt -C OUTPUT -o lo -p tcp -j \"$CHAIN\" 2>/dev/null; then\n    ipt -I OUTPUT 1 -o lo -p tcp -j \"$CHAIN\"\n  fi\n}\n\napply_rules() {\n  local specs=(\"$@\") spec user port other oport\n  for spec in \"${specs[@]}\"; do\n    user=\"${spec%%:*}\"\n    port=\"${spec##*:}\"\n    valid_spec \"$spec\" \"$user\" \"$port\" || exit 2\n  done\n  # Build the whole ruleset and load it with iptables-restore --noflush:\n  # a chain declared in the restore stream is flushed and refilled in ONE\n  # commit, so there is no gap between \"flush old rules\" and \"add new\n  # rules\" where tenant isolation would be down (the old per-rule -F/-A\n  # sequence had exactly that window on every userctl refresh).\n  {\n    echo '*filter'\n    echo \":$CHAIN - [0:0]\"\n    for spec in \"${specs[@]}\"; do\n      user=\"${spec%%:*}\"\n      port=\"${spec##*:}\"\n      # own instance port: allow (both directions of the flow match by dport\n      # here because replies come from sport; the REJECT rules below are the\n      # only destination-scoped denials)\n      echo \"-A $CHAIN -o lo -p tcp -m owner --uid-owner $user --dport $port -m comment --comment $comment -j ACCEPT\"\n    done\n    for spec in \"${specs[@]}\"; do\n      user=\"${spec%%:*}\"\n      port=\"${spec##*:}\"\n      # every OTHER tenant's instance port: rejected by destination\n      # (rule count is O(n^2); fine for dozens of tenants - switch to an\n      # ipset dport set if this ever becomes a problem)\n      for other in \"${specs[@]}\"; do\n        oport=\"${other##*:}\"\n        if [ \"$oport\" != \"$port\" ]; then\n          echo \"-A $CHAIN -o lo -p tcp -m owner --uid-owner $user --dport $oport -m comment --comment $comment -j REJECT --reject-with tcp-reset\"\n        fi\n      done\n      # the gateway itself: a tenant reaching it loopback could spoof another\n      # user's session through the auth front door\n      echo \"-A $CHAIN -o lo -p tcp -m owner --uid-owner $user --dport $GW_PORT -m comment --comment $comment -j REJECT --reject-with tcp-reset\"\n    done\n    echo \"-A $CHAIN -m comment --comment $comment -j RETURN\"\n    echo 'COMMIT'\n  } | iptables-restore --noflush\n  hook_output\n}\n\ncase \"${1:-}\" in\n  --apply)\n    shift\n    [ \"$#\" -ge 1 ] || { echo \"usage: $0 --apply <osuser>:<port> ...\" >&2; exit 2; }\n    apply_rules \"$@\"\n    echo \"loopback guard applied to $*\"\n    ;;\n  --check)\n    ipt -L \"$CHAIN\" >/dev/null 2>&1 && ipt -C OUTPUT -o lo -p tcp -j \"$CHAIN\" 2>/dev/null\n    ;;\n  --remove)\n    ipt -D OUTPUT -o lo -p tcp -j \"$CHAIN\" 2>/dev/null || true\n    ipt -F \"$CHAIN\" 2>/dev/null || true\n    ipt -X \"$CHAIN\" 2>/dev/null || true\n    echo \"loopback guard removed\"\n    ;;\n  *)\n    echo \"usage: $0 --apply <osuser>:<port> [...] | --check | --remove\" >&2\n    exit 2\n    ;;\nesac\n"
    },
    {
      "path": "bin/dsh-file-read",
      "content": "#!/usr/bin/env bash\n# dsh-file-read <home> <path> -- stream a file inside <home> to stdout.\n# exit: 2 usage, 3 out of scope, 4 missing/not a file, 5 hidden dotfile.\n#\n# Security model (fixes issue #1 TOCTOU): root only string-validates args;\n# the actual cat runs as the home's own unprivileged OS account. The\n# realpath prefix check keeps exit-code semantics but is no longer the\n# security boundary.\nset -euo pipefail\nhome=\"$1\"\npath=\"$2\"\n[ -n \"$home\" ] && [ -n \"$path\" ] || exit 2\nname=\"$(basename \"$path\")\"\ncase \"$name\" in .*) exit 5 ;; esac\nosu=\"dsh-$(printf '%s' \"$(basename \"$home\")\" | tr 'A-Z' 'a-z')\"\ncase \"$osu\" in\n  dsh-?*) ;;\n  *) exit 3 ;;\nesac\ncase \"$osu\" in\n  *[!a-z0-9_-]*) exit 3 ;;\nesac\nhd=\"$(realpath \"$home\")\" || exit 3\npd=\"$(realpath \"$path\")\" || exit 4\ncase \"$pd\" in \"$hd\"|\"$hd\"/*) ;; *) exit 3 ;; esac\n[ -f \"$pd\" ] || exit 4\nexec runuser -u \"$osu\" -- cat \"$pd\""
    },
    {
      "path": "units/dsh-loopback-guard.service",
      "content": "# 路径模板：默认前缀 /opt/deepseek-harness。自定义安装时执行\n#   sed \"s|/opt/deepseek-harness|<你的前缀>|g\" units/dsh-loopback-guard.service | sudo tee /etc/systemd/system/dsh-loopback-guard.service\n# 用户/端口映射从 users.json 读取（可用 USERS_FILE 环境变量覆盖），\n# 每次启动重建 iptables 规则；userctl 增删用户时也会即时刷新。\n[Unit]\nDescription=DSH loopback tenant isolation (iptables)\nAfter=network-online.target\nWants=network-online.target\n# 规则基于 users.json 的用户/端口映射，需在用户实例启动前生效\nBefore=dsh-web-*.service\n\n[Service]\nType=oneshot\nEnvironment=USERS_FILE=/opt/deepseek-harness/gateway/users.json\nExecStart=/opt/deepseek-harness/bin/dsh-loopback-guard-apply\nRemainAfterExit=yes\nExecStop=/opt/deepseek-harness/bin/dsh-loopback-guard --remove\n\n[Install]\nWantedBy=multi-user.target\n"
    }
  ],
